// Interactive demo: verbalization lens vs. logit lens.
// Data (DEMO_MODELS, DEMO_IMAGES, DEMO_LABELS, DEMO_WORDS, DEMO_TRANSLATIONS)
// comes from demo_data.js, which is generated by build_demo_data.py.
(function () {
  let currentModel = Object.keys(DEMO_MODELS)[0];
  let currentImg = Object.keys(DEMO_MODELS[currentModel].images)[0];
  let currentLayer = DEMO_MODELS[currentModel].layers[0];
  let cellEls = [];

  // Shade a word by its probability: p=1 is black, low p fades toward light
  // gray. sqrt() compresses the scale, since most probabilities here are small
  // and a linear map would wash every word out to the same pale gray.
  function shade(p) {
    const MAX_GRAY = 170;  // lightest we'll go, so low-p words stay legible
    const level = Math.round(MAX_GRAY * (1 - Math.sqrt(Math.max(0, Math.min(1, p)))));
    return `rgb(${level},${level},${level})`;
  }

  function renderResult(r) {
    // r is a compact tuple [wordIdx, score].
    const word = DEMO_WORDS[r[0]];
    const en = DEMO_TRANSLATIONS[word];
    const translation = en ? `<span class="dm-translation">&rarr; ${en}</span>` : '';
    return `<div class="dm-result"><span class="dm-word" style="color: ${shade(r[1])}">${word}</span>` +
           `${translation}<span class="dm-score">p=${r[1]}</span></div>`;
  }

  function renderResults(elId, results) {
    const el = document.getElementById(elId);
    if (!results || results.length === 0) {
      el.innerHTML = '<div class="dm-hint">(no results)</div>';
      return;
    }
    el.innerHTML = results.map(renderResult).join('');
  }

  function selectPatch(idx) {
    cellEls.forEach(c => c.classList.remove('active'));
    cellEls[idx].classList.add('active');
    const layerData = DEMO_MODELS[currentModel].images[currentImg].by_layer[currentLayer];
    renderResults('dmVerbal', layerData.verballens[idx]);
    renderResults('dmLogit', layerData.raw[idx]);
  }

  function renderLayer() {
    // Keep the user's selection across layer switches; otherwise fall back to
    // the default patch configured in build_demo_data.py.
    const activeIdx = cellEls.findIndex(c => c.classList.contains('active'));
    const d = DEMO_MODELS[currentModel].images[currentImg];
    selectPatch(activeIdx >= 0 ? activeIdx : d.default_patch);
  }

  function makeTabs(containerId, items, isActive, label, onPick) {
    const tabs = document.getElementById(containerId);
    tabs.innerHTML = '';
    items.forEach(item => {
      const t = document.createElement('div');
      t.className = 'dm-tab' + (isActive(item) ? ' active' : '');
      t.textContent = label(item);
      t.onclick = () => {
        tabs.querySelectorAll('.dm-tab').forEach(x => x.classList.remove('active'));
        t.classList.add('active');
        onPick(item);
      };
      tabs.appendChild(t);
    });
  }

  function renderLayerTabs() {
    const layers = DEMO_MODELS[currentModel].layers;
    if (!layers.includes(currentLayer)) currentLayer = layers[0];
    makeTabs('dmLayerTabs', layers, l => l === currentLayer, l => `layer ${l}`, l => {
      currentLayer = l;
      renderLayer();
    });
  }

  function renderImage(name) {
    currentImg = name;
    const d = DEMO_MODELS[currentModel].images[name];
    const wrap = document.getElementById('dmImage');
    wrap.innerHTML = `<img src="${DEMO_IMAGES[name]}" alt="${DEMO_LABELS[name]}">` +
      `<div class="dm-grid" id="dmGrid" style="grid-template-columns: repeat(${d.grid_w}, 1fr); ` +
      `grid-template-rows: repeat(${d.grid_h}, 1fr);"></div>`;
    const overlay = document.getElementById('dmGrid');
    cellEls = [];
    for (let i = 0; i < d.grid_w * d.grid_h; i++) {
      const cell = document.createElement('div');
      cell.className = 'dm-cell';
      cell.onclick = () => {
        // Logged so you can find coordinates to paste into
        // DEFAULT_PATCH_OVERRIDES in build_demo_data.py.
        console.log(`${currentModel} / ${name}: grid ${d.grid_h}x${d.grid_w}, ` +
                    `patch (row ${Math.floor(i / d.grid_w)}, col ${i % d.grid_w}), index ${i}`);
        selectPatch(i);
      };
      overlay.appendChild(cell);
      cellEls.push(cell);
    }
    renderLayerTabs();
    renderLayer();
  }

  function renderImgTabs() {
    const names = Object.keys(DEMO_MODELS[currentModel].images);
    makeTabs('dmImgTabs', names, n => n === currentImg,
             n => DEMO_LABELS[n] || n, renderImage);
  }

  function renderModelTabs() {
    makeTabs('dmModelTabs', Object.keys(DEMO_MODELS), m => m === currentModel,
             m => `${m} (k=${DEMO_MODELS[m].k} OCR heads)`, m => {
      currentModel = m;
      currentImg = Object.keys(DEMO_MODELS[m].images)[0];
      currentLayer = DEMO_MODELS[m].layers[0];
      renderImgTabs();
      renderImage(currentImg);
    });
  }

  renderModelTabs();
  renderImgTabs();
  renderImage(currentImg);
})();
